#include <Arduino.h>
#include <Servo.h>
const int RGB1_R = 2;
const int RGB1_G = 3;
const int RGB1_B = 4;
const int RGB2_R = 5;
const int RGB2_G = 6;
const int RGB2_B = 7;
const int RGB3_R = 8;
const int RGB3_G = 9;
const int RGB3_B = 10;
const int SHCP_PIN = A2;
const int STCP_PIN = A1;
const int DS_PIN = A0;
const int SERVO1_PIN = 11;
const int SERVO2_PIN = 12;
const int SERVO3_PIN = 13;
Servo servo1;
Servo servo2;
Servo servo3;
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};
const int colors[][3] = {
  {255, 0, 0},   
  {0, 255, 0},   
  {0, 255, 255}, 
  {255, 0, 255}, 
  {0, 0, 255},   
  {255, 255, 0}, 
  {255, 255, 255} 
};
int currentColor = 0;
int countdown = 9;

void setup();
void loop();
void setRGBColor(int red, int green, int blue);
void displayNumber(int number);
void setup() {
  pinMode(RGB1_R, OUTPUT);
  pinMode(RGB1_G, OUTPUT);
  pinMode(RGB1_B, OUTPUT);
  pinMode(RGB2_R, OUTPUT);
  pinMode(RGB2_G, OUTPUT);
  pinMode(RGB2_B, OUTPUT);
  pinMode(RGB3_R, OUTPUT);
  pinMode(RGB3_G, OUTPUT);
  pinMode(RGB3_B, OUTPUT);
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  servo1.attach(SERVO1_PIN);
  servo2.attach(SERVO2_PIN);
  servo3.attach(SERVO3_PIN);
  servo1.write(0);
  servo2.write(0);
  servo3.write(0);
  displayNumber(countdown);
}
void loop() {
  setRGBColor(colors[currentColor][0], colors[currentColor][1], colors[currentColor][2]);
  currentColor = (currentColor + 1) % 7;
  displayNumber(countdown);
  if (countdown == 9) {
    servo1.write(0);
    servo2.write(0);
    servo3.write(0);
  } else if (countdown == 6) {
    servo1.write(60);
    servo2.write(60);
    servo3.write(60);
  } else if (countdown == 3) {
    servo1.write(120);
    servo2.write(120);
    servo3.write(120);
  } else if (countdown == 0) {
    servo1.write(180);
    servo2.write(180);
    servo3.write(180);
  }
  delay(2000);
  countdown--;
  if (countdown < 0) {
    countdown = 9;
  }
}
void setRGBColor(int red, int green, int blue) {
  analogWrite(RGB1_R, red);
  analogWrite(RGB1_G, green);
  analogWrite(RGB1_B, blue);
  analogWrite(RGB2_R, red);
  analogWrite(RGB2_G, green);
  analogWrite(RGB2_B, blue);
  analogWrite(RGB3_R, red);
  analogWrite(RGB3_G, green);
  analogWrite(RGB3_B, blue);
}
void displayNumber(int number) {
  byte code = segmentCodes[number];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, code);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
